</main><script>
(()=>{const body=document.getElementById('journal-lines'),add=document.getElementById('add-row');const money={format:cents=>{const absolute=cents<0n?-cents:cents;return (cents<0n?'-':'')+(absolute/100n).toLocaleString('et-EE')+','+(absolute%100n).toString().padStart(2,'0')+' €';}};const cents=value=>{const v=value.trim().replace(',','.');if(!v)return 0n;if(!/^\d{1,13}(?:\.\d{1,2})?$/.test(v))return null;const [whole,fraction='']=v.split('.');return BigInt(whole)*100n+BigInt(fraction.padEnd(2,'0'));};function update(){let debit=0n,credit=0n,valid=true;body.querySelectorAll('tr').forEach(row=>{const d=cents(row.querySelector('[name="debit[]"]').value),c=cents(row.querySelector('[name="credit[]"]').value);if(d===null||c===null||(d>0n&&c>0n))valid=false;debit+=d||0n;credit+=c||0n;});document.getElementById('debit-total').textContent=money.format(debit);document.getElementById('credit-total').textContent=money.format(credit);const balanced=valid&&debit===credit&&debit>0n;document.getElementById('balance-label').textContent=balanced?'TASAKAALUS':valid?'VAHE':'KONTROLLI SUMMASID';const total=document.getElementById('balance-total');total.textContent=money.format(debit>=credit?debit-credit:credit-debit);total.className='total-value '+(balanced?'balance':'unbalanced');const count=body.rows.length;document.getElementById('row-count').textContent=count+' / 20 rida';add.disabled=count>=20;}body.addEventListener('input',update);body.addEventListener('click',event=>{if(event.target.closest('.remove-row')){event.target.closest('tr').remove();update();}});add.addEventListener('click',()=>{if(body.rows.length<20){body.append(document.getElementById('journal-row').content.cloneNode(true));update();body.lastElementChild.querySelector('select').focus();}});update();})();
</script></body></html>
